-- Apply this migration only. Existing authentication migrations are unchanged.
begin;
create table if not exists public.daily_topics(id bigint generated by default as identity primary key,topic text not null);
create table public.sa_usage(day date not null,user_id uuid not null references auth.users on delete cascade,practice int not null default 0,challenge int not null default 0,total int not null default 0,seconds int not null default 0,primary key(day,user_id),check(practice>=0 and challenge>=0 and total>=0 and seconds>=0));
create table public.sa_budget(day date primary key,seconds int not null default 0 check(seconds>=0));
create table public.sa_surveys(user_id uuid primary key references auth.users on delete cascade,answer text not null check(answer in ('yes','maybe','no')),completed_at timestamptz not null default now(),bonus_remaining int not null default 1 check(bonus_remaining between 0 and 1));
create table public.sa_polls(day date primary key,choices jsonb not null check(jsonb_array_length(choices)=3));
create table public.sa_votes(day date not null references public.sa_polls on delete cascade,user_id uuid not null references auth.users on delete cascade,choice_id text not null,primary key(day,user_id));
create table public.sa_challenges(day date primary key,topic text not null);
create table public.sa_jobs(id uuid primary key,user_id uuid not null references auth.users on delete cascade,request_key text not null,digest text not null,metadata jsonb not null,stage text not null default 'upload',status text not null default 'queued',input_path text,upload_url text,provider_id text,result jsonb,error text,usage_day date not null,bonus_spent boolean not null default false,charged boolean not null default false,refunded boolean not null default false,lease_token uuid,leased_until timestamptz,next_run timestamptz not null default now(),deadline timestamptz not null default now()+interval '30 minutes',expires_at timestamptz,coaching_retries int not null default 0,review_retries int not null default 0,created_at timestamptz not null default now(),unique(user_id,request_key));
create index sa_jobs_due on public.sa_jobs(next_run) where stage<>'done';
alter table public.sa_jobs add column stage_attempts int not null default 0;
create table public.sa_daily_attempts(user_id uuid not null references auth.users on delete cascade,day date not null,digest text not null,request_key text not null,job_id uuid references public.sa_jobs on delete set null,state text not null default 'pending',primary key(user_id,day));
create table public.sa_entries(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,job_id uuid,day date not null,name text not null,score int not null check(score between 0 and 100),dimensions jsonb not null,topic text not null,transcript text,rubric_version text not null default 'daily-v1',withdrawn boolean not null default false,created_at timestamptz not null default now(),unique(user_id,day));
create unique index sa_entry_name on public.sa_entries(day,lower(name)) where not withdrawn;
create table public.sa_rates(user_id uuid primary key references auth.users on delete cascade,times timestamptz[] not null default '{}');
create table public.sa_cleanup(id uuid primary key default gen_random_uuid(),input_path text,provider_id text,lease_token uuid,leased_until timestamptz,next_run timestamptz not null default now());
create unique index sa_cleanup_input on public.sa_cleanup(input_path) where input_path is not null;

create function public.sa_day() returns date language sql stable set search_path='' as $$select (now() at time zone 'UTC')::date$$;
create function public.sa_paid(p_user uuid) returns boolean language plpgsql stable security definer set search_path='' as $$
declare s jsonb;begin select raw_app_meta_data->'simplyarticulate_subscription' into s from auth.users where id=p_user;
return coalesce(s->>'status'='active' and (s->>'validUntil')::timestamptz>now(),false);exception when others then return false;end$$;
create function public.sa_fallback_topics() returns text[] language sql immutable set search_path='' as $$select array[
'Describe a small habit that can make a big difference in everyday life.',
'Should schools teach more practical life skills? Explain your position.',
'What makes someone a good leader? Support your answer with an example.',
'Is it better to work alone or as part of a team? Explain why.',
'Describe a lesson people can learn from making mistakes.',
'How can technology help people build stronger communities?',
'What is one change that would improve your local community?',
'Should people spend more time outdoors? Explain the benefits and tradeoffs.']$$;
create function public.sa_challenge() returns jsonb language plpgsql security definer set search_path='' as $$
declare d date:=public.sa_day();t text;pool text[];begin
perform pg_advisory_xact_lock(712901);
select topic into t from public.sa_challenges where day=d;
if t is null then
 select c.value->>'topic' into t from public.sa_polls p cross join lateral jsonb_array_elements(p.choices) with ordinality c(value,ord)
 left join public.sa_votes v on v.day=p.day and v.choice_id=c.value->>'id' where p.day=d group by c.value,c.ord having count(v.user_id)>0 order by count(v.user_id) desc,c.ord limit 1;
 if t is null then select array_agg(topic order by id) into pool from public.daily_topics where length(trim(topic)) between 1 and 500;
 pool:=coalesce(pool,public.sa_fallback_topics());t:=pool[1+mod((d-date '1970-01-01'),cardinality(pool))];end if;
 insert into public.sa_challenges values(d,t) on conflict do nothing;
 select topic into t from public.sa_challenges where day=d;
end if;return jsonb_build_object('id',d,'topic',t);end$$;
create function public.sa_poll(p_user uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare d date:=public.sa_day()+1;t text;pool text[];fallback text[];choices jsonb;total int;mine text;off int;candidate text;begin
perform pg_advisory_xact_lock(712901);t:=public.sa_challenge()->>'topic';
select p.choices into choices from public.sa_polls p where p.day=d;
if choices is null then
 select array_agg(topic order by position) into pool from (select min(id) as position,min(trim(topic)) as topic from public.daily_topics where length(trim(topic)) between 1 and 500 and lower(trim(topic))<>lower(t) group by lower(trim(topic))) x;
 pool:=coalesce(pool,'{}'::text[]);fallback:=public.sa_fallback_topics();
 foreach candidate in array fallback loop if cardinality(pool)>=3 then exit;end if;if lower(candidate)<>lower(t) and not exists(select 1 from unnest(pool) x where lower(x)=lower(candidate)) then pool:=array_append(pool,candidate);end if;end loop;
 off:=mod(d-date '1970-01-01',cardinality(pool));choices:='[]'::jsonb;
 for i in 0..2 loop choices:=choices||jsonb_build_array(jsonb_build_object('id','choice-'||(i+1),'topic',pool[1+mod(off+i,cardinality(pool))]));end loop;
 insert into public.sa_polls values(d,choices);
end if;
select count(*) into total from public.sa_votes where day=d;select choice_id into mine from public.sa_votes where day=d and user_id=p_user;
select jsonb_agg(jsonb_build_object('id',c.value->>'id','topic',c.value->>'topic','votes',n.votes,'percentage',case when total=0 then 0 else round(n.votes*100.0/total,1) end) order by c.ord) into choices from jsonb_array_elements(choices) with ordinality c(value,ord) cross join lateral(select count(*) as votes from public.sa_votes where day=d and choice_id=c.value->>'id') n;
return jsonb_build_object('targetDay',d,'closesAt',(d::timestamp at time zone 'UTC'),'totalVotes',total,'choices',choices)||case when p_user is null then '{}'::jsonb else jsonb_build_object('eligible',true,'myVote',mine) end;end$$;
create function public.sa_vote(p_user uuid,p_day date,p_choice text) returns jsonb language plpgsql security definer set search_path='' as $$
declare ballot jsonb;begin ballot:=public.sa_poll(p_user);if p_day<>public.sa_day()+1 then raise exception 'SA409:Voting for that day has closed.';end if;
if not exists(select 1 from jsonb_array_elements(ballot->'choices') c where c->>'id'=p_choice) then raise exception 'SA400:Choose a listed topic.';end if;
insert into public.sa_votes values(p_day,p_user,p_choice) on conflict(day,user_id) do update set choice_id=excluded.choice_id;return public.sa_poll(p_user);end$$;
create function public.sa_survey(p_user uuid,p_answer text default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare bonus int;begin if p_answer is not null then if p_answer not in ('yes','maybe','no') then raise exception 'SA400:Choose a survey answer.';end if;insert into public.sa_surveys(user_id,answer) values(p_user,p_answer) on conflict do nothing;end if;
select bonus_remaining into bonus from public.sa_surveys where user_id=p_user;return jsonb_build_object('completed',bonus is not null,'bonusRemaining',coalesce(bonus,0));end$$;
create function public.sa_usage_snapshot(p_user uuid,p_format text default 'speech') returns jsonb language plpgsql security definer set search_path='' as $$
declare u public.sa_usage;paid boolean:=public.sa_paid(p_user);kind text:=case when p_format='daily-challenge' then 'challenge' else 'practice' end;used int;lim int;bonus int;begin
select * into u from public.sa_usage where user_id=p_user and day=public.sa_day();used:=case when paid then coalesce(u.total,0) when kind='practice' then coalesce(u.practice,0) else coalesce(u.challenge,0) end;lim:=case when paid then 25 else 1 end;
select case when kind='practice' then bonus_remaining else 0 end into bonus from public.sa_surveys where user_id=p_user;
return jsonb_build_object('paid',paid,'canAnalyze',used<lim or coalesce(bonus,0)>0,'analysesUsed',used,'analysisLimit',lim,'analysesRemaining',greatest(0,lim-used)+coalesce(bonus,0),'category',kind,'practiceUsed',coalesce(u.practice,0),'challengeUsed',coalesce(u.challenge,0),'resetAt',extract(epoch from ((public.sa_day()+1)::timestamp at time zone 'UTC'))*1000);end$$;
create function public.sa_rate(p_user uuid) returns void language plpgsql security definer set search_path='' as $$
declare ts timestamptz[];begin perform pg_advisory_xact_lock(712902);select array_agg(t) into ts from public.sa_rates r cross join unnest(r.times) t where r.user_id=p_user and t>now()-interval '1 minute';ts:=coalesce(ts,'{}'::timestamptz[]);
if cardinality(ts)>=5 then raise exception 'SA429:Please wait a minute before another request.';end if;insert into public.sa_rates values(p_user,array_append(ts,now())) on conflict(user_id) do update set times=excluded.times;end$$;
create function public.sa_reserve_job(p_user uuid,p_id uuid,p_key text,p_digest text,p_metadata jsonb,p_input text) returns public.sa_jobs language plpgsql security definer set search_path='' as $$
declare j public.sa_jobs;u public.sa_usage;a public.sa_daily_attempts;paid boolean:=public.sa_paid(p_user);kind text:=case when p_metadata->>'format'='daily-challenge' then 'challenge' else 'practice' end;bonus boolean:=false;used int;lim int;begin
perform pg_advisory_xact_lock(712903);
if p_input not like p_user::text||'/%' then raise exception 'SA400:Invalid recording path.';end if;
if kind='challenge' and (p_metadata->>'challengeId'<>public.sa_day()::text or p_metadata->>'topic'<>public.sa_challenge()->>'topic') then raise exception 'SA400:Use today''s official challenge topic.';end if;
select * into j from public.sa_jobs where user_id=p_user and request_key=p_key for update;
if j.id is not null then if j.digest<>p_digest then raise exception 'SA409:This request belongs to a different recording.';end if;if j.status<>'error' then return j;end if;if j.stage<>'done' then raise exception 'SA409:The previous attempt is still being cleaned up. Please try again shortly.';end if;end if;
if kind='challenge' then
 if p_metadata->>'challengeId'<>public.sa_day()::text or p_metadata->>'topic'<>public.sa_challenge()->>'topic' then raise exception 'SA400:Use today''s official challenge topic.';end if;
 select * into a from public.sa_daily_attempts where user_id=p_user and day=public.sa_day();
 if a.user_id is not null and (a.state<>'failed' or a.digest<>p_digest or a.request_key<>p_key) then raise exception 'SA429:Today''s competitive take is locked. Retry only the original recording.';end if;
end if;
if (select count(*) from public.sa_jobs where status not in ('completed','error'))>=3 then raise exception 'SA429:Analysis is busy. Please wait for current analyses to finish.';end if;
insert into public.sa_usage(day,user_id) values(public.sa_day(),p_user) on conflict do nothing;select * into u from public.sa_usage where day=public.sa_day() and user_id=p_user;
used:=case when paid then u.total when kind='practice' then u.practice else u.challenge end;lim:=case when paid then 25 else 1 end;
if used>=lim then if kind='practice' and exists(select 1 from public.sa_surveys where user_id=p_user and bonus_remaining=1) then bonus:=true;update public.sa_surveys set bonus_remaining=0 where user_id=p_user;else raise exception 'SA429:Today''s analysis allowance is used. Try again after midnight UTC.';end if;end if;
insert into public.sa_budget(day) values(public.sa_day()) on conflict do nothing;
if (select seconds from public.sa_budget where day=public.sa_day())+300>18000 then raise exception 'SA429:Today''s analysis service budget is full. Try again tomorrow.';end if;
update public.sa_budget set seconds=seconds+300 where day=public.sa_day();
update public.sa_usage set practice=practice+case when kind='practice' then 1 else 0 end,challenge=challenge+case when kind='challenge' then 1 else 0 end,total=total+1,seconds=seconds+300 where day=public.sa_day() and user_id=p_user;
if j.id is null then insert into public.sa_jobs(id,user_id,request_key,digest,metadata,input_path,usage_day,bonus_spent,stage,next_run) values(p_id,p_user,p_key,p_digest,p_metadata,p_input,public.sa_day(),bonus,'awaiting-upload',now()+interval '2 minutes') returning * into j;
else update public.sa_jobs set input_path=p_input,usage_day=public.sa_day(),bonus_spent=bonus,charged=false,refunded=false,result=null,error=null,stage='awaiting-upload',status='queued',lease_token=null,leased_until=null,next_run=now()+interval '2 minutes',deadline=now()+interval '30 minutes',expires_at=null where id=j.id returning * into j;end if;
if kind='challenge' then insert into public.sa_daily_attempts values(p_user,public.sa_day(),p_digest,p_key,j.id,'pending') on conflict(user_id,day) do update set job_id=excluded.job_id,state='pending';end if;return j;end$$;
create function public.sa_ready_upload(p_user uuid,p_id uuid) returns public.sa_jobs language plpgsql security definer set search_path='' as $$declare j public.sa_jobs;begin select * into j from public.sa_jobs where id=p_id and user_id=p_user for update;if j.id is null then raise exception 'SA404:Analysis not found.';end if;if j.stage='awaiting-upload' then update public.sa_jobs set stage='upload',next_run=now(),lease_token=null,leased_until=null where id=j.id returning * into j;end if;return j;end$$;
create function public.sa_claim_job(p_id uuid default null) returns public.sa_jobs language plpgsql security definer set search_path='' as $$
declare j public.sa_jobs;begin
select * into j from public.sa_jobs where stage<>'done' and next_run<=now() and (leased_until is null or leased_until<now()) and (p_id is null or id=p_id) order by next_run limit 1 for update skip locked;
if j.id is null then return null;end if;update public.sa_jobs set lease_token=gen_random_uuid(),leased_until=now()+interval '120 seconds',stage_attempts=case when stage in ('upload','submit','verify','coach','review') then stage_attempts+1 else 0 end where id=j.id returning * into j;return j;end$$;
create function public.sa_save_stage(p_id uuid,p_lease uuid,p_stage text,p_status text,p_result jsonb,p_provider text,p_upload text,p_delay int default 0,p_error text default null) returns boolean language plpgsql security definer set search_path='' as $$
begin update public.sa_jobs set stage=p_stage,status=p_status,result=p_result,provider_id=p_provider,upload_url=p_upload,error=p_error,stage_attempts=0,next_run=now()+make_interval(secs=>greatest(0,p_delay)),lease_token=null,leased_until=null,expires_at=case when p_status in ('completed','error') then now()+interval '30 minutes' else expires_at end where id=p_id and lease_token=p_lease and leased_until>now();if not found then return false;end if;
if p_status='completed' then update public.sa_daily_attempts set state='completed' where job_id=p_id;end if;return true;end$$;
create function public.sa_charge_job(p_id uuid,p_lease uuid,p_seconds int) returns boolean language plpgsql security definer set search_path='' as $$
declare j public.sa_jobs;begin perform pg_advisory_xact_lock(712903);select * into j from public.sa_jobs where id=p_id and lease_token=p_lease and leased_until>now() for update;if j.id is null then return false;end if;
if not j.charged and not j.refunded then update public.sa_usage set seconds=greatest(0,seconds-300+least(302,greatest(1,p_seconds))) where day=j.usage_day and user_id=j.user_id;update public.sa_budget set seconds=greatest(0,seconds-300+least(302,greatest(1,p_seconds))) where day=j.usage_day;update public.sa_jobs set charged=true where id=j.id;end if;return true;end$$;
create function public.sa_store_transcript(p_id uuid,p_lease uuid,p_result jsonb,p_seconds int) returns boolean language plpgsql security definer set search_path='' as $$begin
if not public.sa_charge_job(p_id,p_lease,p_seconds) then return false;end if;
return public.sa_save_stage(p_id,p_lease,'verify','coaching',p_result,(select provider_id from public.sa_jobs where id=p_id),(select upload_url from public.sa_jobs where id=p_id),0,null);end$$;
create function public.sa_fail_job(p_id uuid,p_lease uuid,p_error text) returns boolean language plpgsql security definer set search_path='' as $$
declare j public.sa_jobs;kind text;begin perform pg_advisory_xact_lock(712903);select * into j from public.sa_jobs where id=p_id and (p_lease is null or lease_token=p_lease) for update;if j.id is null then return false;end if;
if not j.charged and not j.refunded then kind:=case when j.metadata->>'format'='daily-challenge' then 'challenge' else 'practice' end;update public.sa_usage set practice=greatest(0,practice-case when kind='practice' then 1 else 0 end),challenge=greatest(0,challenge-case when kind='challenge' then 1 else 0 end),total=greatest(0,total-1),seconds=greatest(0,seconds-300) where day=j.usage_day and user_id=j.user_id;if j.provider_id is null and j.stage not in ('submit','transcribe','verify','coach','review') then update public.sa_budget set seconds=greatest(0,seconds-300) where day=j.usage_day;end if;if j.bonus_spent then update public.sa_surveys set bonus_remaining=1 where user_id=j.user_id;end if;end if;
update public.sa_jobs set stage='cleanup',status='error',error=p_error,refunded=not charged or refunded,next_run=now(),lease_token=null,leased_until=null,expires_at=now()+interval '30 minutes' where id=j.id;
update public.sa_daily_attempts set state='failed' where job_id=j.id and state<>'completed';return true;end$$;
create function public.sa_retry(p_user uuid,p_id uuid,p_kind text,p_transcript text default null) returns public.sa_jobs language plpgsql security definer set search_path='' as $$
declare j public.sa_jobs;begin perform pg_advisory_xact_lock(712903);select * into j from public.sa_jobs where id=p_id and user_id=p_user for update;if j.id is null then raise exception 'SA404:Analysis not found or expired.';end if;if j.status<>'completed' or j.stage not in ('done','cleanup') then raise exception 'SA409:Wait for analysis to finish.';end if;
if p_kind='coaching' then
 if p_transcript is distinct from j.result->>'transcript' then raise exception 'SA400:Retry coaching on the original transcript.';end if;
 if j.result->'coaching' is not null and j.result->'coaching'<>'null'::jsonb then return j;end if;
 if j.coaching_retries>=3 then raise exception 'SA429:Coaching retry limit reached. Your transcript is retained.';end if;
 update public.sa_jobs set stage='verify',status='coaching',coaching_retries=coaching_retries+1 where id=j.id;
elsif p_kind='review' then
 if j.metadata->>'format'<>'daily-challenge' or coalesce((j.result#>>'{communityReview,retryable}')::boolean,false)=false then raise exception 'SA409:This take already has a community review.';end if;
 if j.review_retries>=3 then raise exception 'SA429:Community review retry limit reached.';end if;
 update public.sa_jobs set stage='review',status='moderating',review_retries=review_retries+1 where id=j.id;
else raise exception 'SA400:Invalid retry request.';end if;
update public.sa_jobs set lease_token=null,leased_until=null,stage_attempts=0,next_run=now(),deadline=now()+interval '30 minutes',expires_at=null where id=j.id returning * into j;return j;end$$;
create function public.sa_public_entries(p_day date) returns jsonb language sql stable security definer set search_path='' as $$
select jsonb_build_object('day',p_day,'entries',coalesce(jsonb_agg(jsonb_build_object('id',id,'day',day,'name',name,'score',score,'dimensions',dimensions,'topic',topic,'transcript',transcript,'createdAt',created_at,'rubricVersion',rubric_version,'rank',rank) order by score desc,created_at),'[]'::jsonb)) from (select *,rank() over(order by score desc) as rank from public.sa_entries where day=p_day and not withdrawn order by score desc,created_at limit 100) e$$;
create function public.sa_publish(p_user uuid,p_job uuid,p_share boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare j public.sa_jobs;e public.sa_entries;r jsonb;dims jsonb;begin perform pg_advisory_xact_lock(712904);select * into j from public.sa_jobs where id=p_job and user_id=p_user;if j.id is null then raise exception 'SA404:Analysis not found.';end if;
if j.status<>'completed' or j.metadata->>'format'<>'daily-challenge' or j.metadata->>'challengeId'<>public.sa_day()::text then raise exception 'SA409:Complete today''s daily challenge first.';end if;r:=j.result->'communityReview';
if r->>'moderation'<>'allow' or coalesce((r->>'eligible')::boolean,false)=false then raise exception 'SA409:This take has not passed community review.';end if;
select * into e from public.sa_entries where user_id=p_user and day=public.sa_day();if e.id is not null then if e.withdrawn or e.job_id<>j.id then raise exception 'SA409:You already entered today. Scores cannot be replaced.';end if;else
select jsonb_agg(jsonb_build_object('name',d->>'name','score',(d->>'score')::int)) into dims from jsonb_array_elements(r->'dimensions') d;
insert into public.sa_entries(user_id,job_id,day,name,score,dimensions,topic,transcript) values(p_user,j.id,public.sa_day(),j.metadata->>'publicUsername',(r->>'score')::int,dims,j.metadata->>'topic',case when p_share then j.result->>'transcript' else null end) returning * into e;end if;
return to_jsonb(e)-'user_id'-'job_id'-'withdrawn';exception when unique_violation then raise exception 'SA409:That username is already used today.';end$$;
create function public.sa_queue_cleanup() returns trigger language plpgsql security definer set search_path='' as $$begin if old.input_path is not null or old.provider_id is not null then insert into public.sa_cleanup(input_path,provider_id) values(old.input_path,old.provider_id) on conflict do nothing;end if;return old;end$$;
create trigger sa_job_removed before delete on public.sa_jobs for each row execute function public.sa_queue_cleanup();
create function public.sa_claim_cleanup() returns public.sa_cleanup language plpgsql security definer set search_path='' as $$declare c public.sa_cleanup;begin select * into c from public.sa_cleanup where next_run<=now() and (leased_until is null or leased_until<now()) limit 1 for update skip locked;if c.id is null then return null;end if;update public.sa_cleanup set lease_token=gen_random_uuid(),leased_until=now()+interval '120 seconds' where id=c.id returning * into c;return c;end$$;
create function public.sa_expire_jobs() returns void language plpgsql security definer set search_path='' as $$begin
delete from public.sa_jobs where stage='done' and expires_at<now();delete from public.sa_rates where not exists(select 1 from unnest(times) t where t>now()-interval '1 hour');
insert into public.sa_cleanup(input_path) select o.name from storage.objects o where o.bucket_id='sa-analysis-inputs' and o.created_at<now()-interval '30 minutes' and not exists(select 1 from public.sa_jobs j where j.input_path=o.name) and not exists(select 1 from public.sa_cleanup c where c.input_path=o.name) limit 50 on conflict do nothing;end$$;
create function public.sa_health() returns jsonb language plpgsql security definer set search_path='' as $$declare ready boolean:=false;begin if to_regclass('cron.job') is not null then execute 'select exists(select 1 from cron.job where jobname=''sa-speech-worker'' and active)' into ready;end if;return jsonb_build_object('scheduler',ready);end$$;
create function public.sa_upload_failed(p_user uuid,p_id uuid) returns void language plpgsql security definer set search_path='' as $$begin perform pg_advisory_xact_lock(712903);if exists(select 1 from public.sa_jobs where id=p_id and user_id=p_user and stage='awaiting-upload') then perform public.sa_fail_job(p_id,null,'Recording upload could not finish. Keep your original take and retry.');end if;end$$;
create function public.sa_import_local_state(p_state jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare d record;u record;x jsonb;owner uuid;choices jsonb;topic text;pool text[];j_id uuid;state text;begin
perform pg_advisory_xact_lock(712903);perform pg_advisory_xact_lock(712901);
for d in select * from jsonb_each(coalesce(p_state#>'{counts,days}','{}')) loop for u in select * from jsonb_each(d.value) loop
 if u.key!~*'^[0-9a-f-]{36}$' then continue;end if;owner:=u.key::uuid;if not exists(select 1 from auth.users where id=owner) then continue;end if;
 insert into public.sa_usage(day,user_id,practice,challenge,total) values(d.key::date,owner,case when jsonb_typeof(u.value)='number' then (u.value::text)::int else coalesce((u.value->>'practice')::int,0) end,coalesce((u.value->>'challenge')::int,0),case when jsonb_typeof(u.value)='number' then (u.value::text)::int else coalesce((u.value->>'total')::int,0) end)
 on conflict(day,user_id) do update set practice=greatest(sa_usage.practice,excluded.practice),challenge=greatest(sa_usage.challenge,excluded.challenge),total=greatest(sa_usage.total,excluded.total);
 end loop;end loop;
for u in select * from jsonb_each(coalesce(p_state#>'{counts,surveys}','{}')) loop if u.key!~*'^[0-9a-f-]{36}$' then continue;end if;owner:=u.key::uuid;if exists(select 1 from auth.users where id=owner) then insert into public.sa_surveys(user_id,answer,completed_at,bonus_remaining) values(owner,u.value->>'answer',coalesce((u.value->>'completedAt')::timestamptz,now()),coalesce((u.value->>'bonusRemaining')::int,0)) on conflict do nothing;end if;end loop;
for u in select * from jsonb_each(coalesce(p_state#>'{seconds,users}','{}')) loop if u.key!~*'^[0-9a-f-]{36}$' then continue;end if;owner:=u.key::uuid;if exists(select 1 from auth.users where id=owner) then insert into public.sa_usage(day,user_id,seconds) values((p_state#>>'{seconds,day}')::date,owner,(u.value::text)::int) on conflict(day,user_id) do update set seconds=greatest(sa_usage.seconds,excluded.seconds);end if;end loop;
if p_state#>>'{seconds,day}' is not null then insert into public.sa_budget values((p_state#>>'{seconds,day}')::date,coalesce((p_state#>>'{seconds,total}')::int,0)) on conflict(day) do update set seconds=greatest(sa_budget.seconds,excluded.seconds);end if;
for d in select * from jsonb_each(coalesce(p_state#>'{voting,challenges}','{}')) loop insert into public.sa_challenges values(d.key::date,d.value#>>'{}') on conflict do nothing;end loop;
for d in select * from jsonb_each(coalesce(p_state#>'{voting,polls}','{}')) loop
 choices:=d.value->'choices';pool:=public.sa_fallback_topics();foreach topic in array pool loop if jsonb_array_length(choices)>=3 then exit;end if;if not exists(select 1 from jsonb_array_elements(choices) c where lower(c->>'topic')=lower(topic)) then choices:=choices||jsonb_build_array(jsonb_build_object('id','choice-'||(jsonb_array_length(choices)+1),'topic',topic));end if;end loop;
 insert into public.sa_polls values(d.key::date,choices) on conflict do nothing;
 for x in select * from jsonb_array_elements(coalesce(d.value->'votes','[]')) loop if x->>'owner'!~*'^[0-9a-f-]{36}$' then continue;end if;owner:=(x->>'owner')::uuid;if exists(select 1 from auth.users where id=owner) then insert into public.sa_votes values(d.key::date,owner,x->>'choiceId') on conflict do nothing;end if;end loop;
end loop;
for x in select * from jsonb_array_elements(coalesce(p_state->'attempts','[]')) loop
 if x->>'owner'!~*'^[0-9a-f-]{36}$' then continue;end if;owner:=(x->>'owner')::uuid;if not exists(select 1 from auth.users where id=owner) then continue;end if;state:=coalesce(x->>'state','completed');j_id:=null;
 if state='completed' and x->'result' is not null and x->'result'<>'null'::jsonb and (x->>'recoveryUntil')::numeric>extract(epoch from now())*1000 then
 j_id:=coalesce((x->>'jobId')::uuid,gen_random_uuid());
 insert into public.sa_jobs(id,user_id,request_key,digest,metadata,stage,status,result,usage_day,charged,expires_at) values(j_id,owner,coalesce(x->>'requestKey','legacy-'||j_id),coalesce(x->>'digest','legacy'),x->'metadata','done','completed',x->'result',(x->>'day')::date,true,to_timestamp((x->>'recoveryUntil')::numeric/1000)) on conflict do nothing;
 end if;
 insert into public.sa_daily_attempts values(owner,(x->>'day')::date,coalesce(x->>'digest','legacy'),coalesce(x->>'requestKey','legacy'),j_id,case when state in ('failed','pending') then 'failed' else 'completed' end) on conflict do nothing;
end loop;
for x in select * from jsonb_array_elements(coalesce(p_state->'community','[]')) loop if x->>'owner'!~*'^[0-9a-f-]{36}$' then continue;end if;owner:=(x->>'owner')::uuid;if exists(select 1 from auth.users where id=owner) then insert into public.sa_entries(id,user_id,job_id,day,name,score,dimensions,topic,transcript,rubric_version,withdrawn,created_at) values((x->>'id')::uuid,owner,(x->>'sourceJob')::uuid,(x->>'day')::date,x->>'name',(x->>'score')::int,coalesce(x->'dimensions','[]'),x->>'topic',x->>'transcript',coalesce(x->>'rubricVersion','daily-v1'),coalesce((x->>'withdrawn')::boolean,false),(x->>'createdAt')::timestamptz) on conflict do nothing;end if;end loop;
return jsonb_build_object('imported',true);end$$;

insert into storage.buckets(id,name,public,file_size_limit) values('sa-analysis-inputs','sa-analysis-inputs',false,12582912) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit;
-- Clients have no direct access. Every API write verifies Supabase Auth first.
do $$declare t text;r record;begin
foreach t in array array['sa_usage','sa_budget','sa_surveys','sa_polls','sa_votes','sa_challenges','sa_jobs','sa_daily_attempts','sa_entries','sa_rates','sa_cleanup'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;
for r in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'sa\_%' escape '\' loop execute format('revoke all on function %s from public,anon,authenticated',r.signature);execute format('grant execute on function %s to service_role',r.signature);end loop;end$$;
commit;
